    #[test]
    fn gravity_sets_ticks_and_grounds_levitator() {
        // Bronzor (Levitate) is airborne — Earth Power is immune. After
        // Bronzor's own Gravity lands, the field condition grounds it and
        // a Ground move now connects. PS data/moves.ts:gravity.
        let p1_json = r#"[
            {"species":"bronzor","level":50,"ability":"levitate","item":"","nature":"calm","moves":["gravity","zenheadbutt","bodyslam","rest"],"evs":{"hp":252,"spd":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"sandveil","item":"","nature":"adamant","moves":["earthpower","earthquake","dragonclaw","ironhead"],"evs":{"spa":252,"spe":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        // Pre-gravity: Bronzor is airborne (Levitate), Ground-immune.
        assert!(!b.p1.team[0].is_grounded(), "Bronzor airborne before Gravity");
        // Turn 1: Bronzor uses Gravity (Garchomp Earth Power whiffs on the
        // still-airborne mon this same turn only if it moved first; Bronzor
        // is slower so Garchomp moves first into an airborne target → no
        // damage). We only assert the field state here.
        let hp_before = b.p1.team[0].current_hp;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        assert_eq!(b.gravity_turns, 4, "Gravity set to 5, ticked to 4");
        assert!(b.p1.team[0].is_grounded(), "Bronzor grounded under Gravity");
        // Earth Power into airborne Bronzor on turn 1 (before Gravity) did
        // nothing.
        assert_eq!(b.p1.team[0].current_hp, hp_before, "EQ immune turn 1");
        // Turn 2: now grounded, Earth Power connects. Bronzor uses Zen
        // Headbutt (slot 1) — a non-healing move so its HP only moves down.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        assert!(b.p1.team[0].current_hp < hp_before, "Earth Power hits grounded Bronzor");
        assert_eq!(b.gravity_turns, 3, "Gravity ticked to 3");
    }

    #[test]
    fn gravity_disables_airborne_move() {
        // While Gravity is up, Fly (gravity-flagged) can't be used — it
        // does nothing and (per PS `cant`) charges no PP.
        let p1_json = r#"[
            {"species":"cresselia","level":50,"ability":"levitate","item":"","nature":"relaxed","moves":["gravity","moonlight","helpinghand","psychic"]}
        ]"#;
        // Skarmory (base Spe 70) is slower than Cresselia (85), so Gravity
        // resolves first and the same-turn Fly is already disabled.
        let p2_json = r#"[
            {"species":"skarmory","level":50,"ability":"sturdy","item":"","nature":"sassy","moves":["fly","spikes","roost","ironhead"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 3 }, p1, p2);
        // Turn 1: Cresselia sets Gravity; Skarmory tries Fly.
        let fly_pp_before = b.p2.team[0].pp[0];
        let cress_hp_before = b.p1.team[0].current_hp;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
        );
        assert!(b.gravity_turns > 0, "Gravity active");
        // Fly was canceled — no charge state, no PP spent, no damage.
        assert_eq!(b.p2.team[0].pp[0], fly_pp_before, "Fly charged no PP (cant)");
        assert_eq!(b.p2.team[0].semi_invuln, 0, "Fly did not enter semi-invuln");
        assert_eq!(b.p1.team[0].current_hp, cress_hp_before, "Fly dealt no damage");
    }

    #[test]
    fn sleep_talk_fires_while_asleep_but_regular_move_is_skipped() {
        // PS `slp` onBeforeMove allows `sleepUsable` moves (Sleep Talk) to
        // proceed while the user stays asleep; non-sleepUsable moves are
        // skipped with no PP. Observable: Sleep Talk's own PP IS spent
        // while asleep (it reaches resolution), whereas a normal move's PP
        // is NOT spent (skipped before PP deduct).
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","crunch","sleeptalk","earthquake"],"evs":{"hp":252,"spd":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"pikachu","level":50,"ability":"static","item":"","nature":"hardy","moves":["thunderbolt","quickattack","grassknot","feint"]}
        ]"#;
        // Case A: asleep Snorlax uses Sleep Talk (slot 2) → PP spent.
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 9 }, p1, p2);
        b.p1.team[0].status = Status::Sleep;
        b.p1.team[0].set_sleep_turns(3);
        let st_pp = b.p1.team[0].pp[2];
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 2, target: None }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(b.p1.team[0].sleep_turns() < 3, "sleep counter ticked");
        assert_eq!(b.p1.team[0].pp[2], st_pp - 1, "Sleep Talk PP spent while asleep");

        // Case B: asleep Snorlax uses Body Slam (slot 0) → skipped, no PP.
        let p1b = TeamBuilder::from_json(p1_json).unwrap();
        let p2b = TeamBuilder::from_json(p2_json).unwrap();
        let mut b2 = Battle::new(BattleConfig { format: Format::Singles, seed: 9 }, p1b, p2b);
        b2.p1.team[0].status = Status::Sleep;
        b2.p1.team[0].set_sleep_turns(3);
        let bs_pp = b2.p1.team[0].pp[0];
        b2.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b2.p1.team[0].pp[0], bs_pp, "regular move skipped while asleep, no PP");
    }

    #[test]
    fn skill_swap_exchanges_abilities_and_resets_on_switch() {
        // Jirachi (Serene Grace) Skill Swaps with Garchomp (Rough Skin):
        // each effective ability becomes the other's. PS skillSwap.
        let p1_json = r#"[
            {"species":"jirachi","level":50,"ability":"serenegrace","item":"","nature":"timid","moves":["skillswap","mudslap","meteorbeam","imprison"],"evs":{"spe":252,"spd":252}},
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","crunch","yawn"]}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"jolly","moves":["earthquake","dragonclaw","protect","ironhead"],"evs":{"spe":252,"atk":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 5 }, p1, p2);
        assert_eq!(b.p1.team[0].effective_ability_slug(), "serenegrace");
        assert_eq!(b.p2.team[0].effective_ability_slug(), "roughskin");
        // Jirachi (faster) Skill Swaps into Garchomp. Garchomp uses Dragon
        // Claw (NOT Protect — a Protecting target would correctly block the
        // swap; see skill_swap_blocked_by_protect).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P1, 0)) }],
        );
        assert_eq!(b.p1.team[0].effective_ability_slug(), "roughskin", "Jirachi got Rough Skin");
        assert_eq!(b.p2.team[0].effective_ability_slug(), "serenegrace", "Garchomp got Serene Grace");
        // Base ids are untouched (override only).
        assert_ne!(b.p1.team[0].ability_override, u16::MAX);
        // Switch Jirachi out → override clears.
        b.step(
            &[Choice::Switch { actor_slot: 0, team_index: 1 }],
            &[Choice::Move { actor_slot: 0, move_slot: 2, target: None }],
        );
        assert_eq!(b.p1.team[0].ability_override, u16::MAX, "override reset on switch-out");
        assert_eq!(b.p1.team[0].effective_ability_slug(), "serenegrace", "Jirachi back to base ability");
    }

    #[test]
    fn skill_swap_blocked_by_protect() {
        // Skill Swap has the `protect` flag, so a Protecting target blocks the
        // swap entirely — both abilities stay put (Champions conformance out_45).
        let p1_json = r#"[
            {"species":"jirachi","level":50,"ability":"serenegrace","item":"","nature":"timid","moves":["skillswap","mudslap","meteorbeam","imprison"],"evs":{"spe":252,"spd":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"jolly","moves":["earthquake","dragonclaw","protect","ironhead"],"evs":{"spe":252,"atk":252}}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 5 }, p1, p2);
        // Jirachi Skill Swaps; Garchomp Protects (move_slot 2).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 2, target: None }],
        );
        assert_eq!(b.p1.team[0].effective_ability_slug(), "serenegrace", "Jirachi keeps its ability — Protect blocked the swap");
        assert_eq!(b.p2.team[0].effective_ability_slug(), "roughskin", "Garchomp keeps Rough Skin");
        assert_eq!(b.p1.team[0].ability_override, u16::MAX, "no override applied");
    }

