        let p1_json = r#"[
            {"species":"pikachu","level":50,"ability":"static","item":"focussash","nature":"hardy","moves":["lightscreen","thunderbolt","quickattack","grassknot"]}
        ]"#;
        let p2_json = r#"[
            {"species":"pikachu","level":50,"ability":"static","item":"focussash","nature":"hardy","moves":["lightscreen","thunderbolt","quickattack","grassknot"]}
        ]"#;
