    #[test]
    fn soak_changes_target_to_pure_water() {
        // PS data/moves.ts:soak — the target becomes mono-Water.
        let p1_json = r#"[
            {"species":"politoed","level":50,"ability":"drizzle","nature":"modest","moves":["soak","scald","protect","icebeam"]}
        ]"#;
        // Garchomp (Dragon/Ground) → pure Water.
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","nature":"jolly","moves":["earthquake","dragonclaw","protect","swordsdance"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 9 }, p1, p2);
        let (_, n0) = b.p2.team[0].effective_types();
        assert_eq!(n0, 2, "Garchomp starts dual-typed");
        // Garchomp idles with Swords Dance (self), NOT Protect: Soak carries
        // `flags.protect` and would be blocked by a Protecting target.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 3, target: None }],
        );
        let (types, n) = b.p2.team[0].effective_types();
        assert_eq!(n, 1, "Soak makes the target mono-typed");
        assert_eq!(types[0], 2, "target becomes pure Water (type code 2)");
    }

    #[test]
    fn psych_up_copies_targets_stat_stages() {
        let alakazam = r#"[
            {"species":"alakazam","level":50,"ability":"magicguard","nature":"timid","moves":["psychup","protect","psychic","calmmind"]}
        ]"#;
        let garchomp = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","nature":"jolly","moves":["swordsdance","protect","earthquake","dragonclaw"]}
        ]"#;
        let p1 = TeamBuilder::from_json(alakazam).unwrap();
        let p2 = TeamBuilder::from_json(garchomp).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        // Turn 1: Garchomp Swords Dance (+2 Atk); Alakazam Protect.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
        );
        assert_eq!(b.p2.team[0].boosts[0], 2, "Garchomp at +2 Atk");
        assert_eq!(b.p1.team[0].boosts[0], 0, "Alakazam not yet boosted");
        // Turn 2: Alakazam Psych Up copies Garchomp's stages; Garchomp Protect
        // (no boost change).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
        );
        assert_eq!(b.p1.team[0].boosts[0], 2, "Psych Up copied Garchomp's +2 Atk");
    }

    fn destiny_bond_setup() -> Battle {
        // Fast Gengar (Destiny Bond) vs slow Snorlax. Snorlax's attacking
        // slot 0 is Earthquake — Ground hits Ghost/Poison Gengar (Normal
        // moves like Body Slam are immune vs the Ghost type).
        let gengar = r#"[
            {"species":"gengar","level":50,"ability":"cursedbody","nature":"timid","moves":["destinybond","shadowball","sludgebomb","protect"]}
        ]"#;
        let snorlax = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","nature":"brave","moves":["earthquake","amnesia","rest","headbutt"]}
        ]"#;
        let p1 = TeamBuilder::from_json(gengar).unwrap();
        let p2 = TeamBuilder::from_json(snorlax).unwrap();
        Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2)
    }

    #[test]
    fn destiny_bond_faints_attacker_that_kos_the_holder() {
        let mut b = destiny_bond_setup();
        b.p1.team[0].current_hp = 1; // Gengar will be KO'd by Body Slam
        // Gengar (faster) uses Destiny Bond → volatile set; Snorlax Body Slam
        // KOs Gengar → Destiny Bond faints Snorlax too.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
        );
        assert!(b.p1.team[0].fainted, "Gengar fainted to Body Slam");
        assert!(b.p2.team[0].fainted, "Destiny Bond fainted the attacker (Snorlax)");
    }

    #[test]
    fn destiny_bond_clears_when_holder_acts_again() {
        let mut b = destiny_bond_setup();
        // Turn 1: Gengar sets Destiny Bond; Snorlax just boosts (no KO).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
        );
        assert!(b.p1.team[0].volatiles.has(crate::pokemon::VolatileKind::DestinyBond));
        // Turn 2: Gengar (faster) uses Shadow Ball — Destiny Bond clears as it
        // acts — then Snorlax KOs the 1-HP Gengar. No faint-back.
        b.p1.team[0].current_hp = 1;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
        );
        assert!(b.p1.team[0].fainted, "Gengar fainted");
        assert!(!b.p2.team[0].fainted, "Destiny Bond already cleared — attacker survives");
    }

    #[test]
    fn destiny_bond_consecutive_use_fails() {
        let mut b = destiny_bond_setup();
        // Turn 1: Destiny Bond sets the volatile.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
        );
        assert!(b.p1.team[0].volatiles.has(crate::pokemon::VolatileKind::DestinyBond));
        // Turn 2: Destiny Bond again → onPrepareHit removes the volatile and
        // the move fails (no protection this turn).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 1, target: None }],
        );
        assert!(
            !b.p1.team[0].volatiles.has(crate::pokemon::VolatileKind::DestinyBond),
            "consecutive Destiny Bond fails and clears the volatile"
        );
    }

    #[test]
    fn electric_terrain_boosts_electric_damage_on_grounded() {
        // Same Thunderbolt vs grounded Pikachu, with and without
        // Electric Terrain — ×1.3 boost.
        let p1_json = r#"[
            {"species":"pikachu","level":50,"ability":"static","nature":"modest","moves":["thunderbolt","quickattack","grassknot","feint"],"evs":{"spa":252,"spe":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"blissey","level":50,"ability":"naturalcure","nature":"calm","moves":["softboiled","seismictoss","protect","reflect"],"evs":{"hp":252,"spd":252,"def":4}}
        ]"#;
        let p1a = TeamBuilder::from_json(p1_json).unwrap();
        let p2a = TeamBuilder::from_json(p2_json).unwrap();
        let p1b = TeamBuilder::from_json(p1_json).unwrap();
        let p2b = TeamBuilder::from_json(p2_json).unwrap();
        let mut no_terrain = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1a, p2a);
        let start_hp = no_terrain.p2.team[0].current_hp;
        no_terrain.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        let dmg_no = start_hp - no_terrain.p2.team[0].current_hp;

        let mut with_terrain = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1b, p2b);
        with_terrain.terrain = crate::terrain::Terrain::Electric;
        with_terrain.terrain_turns = 5;
        let start_hp_b = with_terrain.p2.team[0].current_hp;
        with_terrain.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        let dmg_with = start_hp_b - with_terrain.p2.team[0].current_hp;
        let pct = dmg_with as i32 * 100 / dmg_no as i32;
        assert!((125..=135).contains(&pct), "expected ~130%; got {pct}%");
    }

    #[test]
    fn electric_terrain_does_not_boost_flying_defender() {
        // Pelipper is Water/Flying — ungrounded → no terrain boost.
        let p1_json = r#"[
            {"species":"pikachu","level":50,"ability":"static","nature":"modest","moves":["thunderbolt","quickattack","grassknot","feint"]}
        ]"#;
        let p2_json = r#"[
            {"species":"pelipper","level":50,"ability":"drizzle","nature":"calm","moves":["hurricane","weatherball","tailwind","airslash"]}
        ]"#;
        let p1a = TeamBuilder::from_json(p1_json).unwrap();
        let p2a = TeamBuilder::from_json(p2_json).unwrap();
        let p1b = TeamBuilder::from_json(p1_json).unwrap();
        let p2b = TeamBuilder::from_json(p2_json).unwrap();
        let mut no_terrain = Battle::new(BattleConfig { format: Format::Singles, seed: 11 }, p1a, p2a);
        // Pelipper sets Rain on switch-in — that's neutral for the test
        // (electric damage doesn't care about rain).
        let _ = no_terrain.weather;
        let start = no_terrain.p2.team[0].current_hp;
        no_terrain.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        let dmg_no = start - no_terrain.p2.team[0].current_hp;

        let mut with_terrain = Battle::new(BattleConfig { format: Format::Singles, seed: 11 }, p1b, p2b);
        with_terrain.terrain = crate::terrain::Terrain::Electric;
        with_terrain.terrain_turns = 5;
        let start_b = with_terrain.p2.team[0].current_hp;
        with_terrain.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        let dmg_with = start_b - with_terrain.p2.team[0].current_hp;
        // Should be equal (Flying = ungrounded). Allow ±1 HP rounding.
        let diff = (dmg_with as i32 - dmg_no as i32).abs();
        assert!(diff <= 1, "Flying Pelipper not boosted by E-Terrain; got {dmg_with} vs {dmg_no}");
    }

    #[test]
    fn mirror_herb_copies_opposing_dragon_dance() {
        // Garchomp Dragon Dances (+1 Atk, +1 Spe). Snorlax holds Mirror
        // Herb — should mirror both boosts and consume.
        let p1_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","nature":"jolly","moves":["dragondance","dragonclaw","earthquake","protect"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","nature":"hardy","item":"mirrorherb","moves":["bodyslam","rest","sleeptalk","headbutt"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(b.p1.team[0].boosts[0], 1, "Garchomp +1 Atk from DD");
        assert_eq!(b.p1.team[0].boosts[4], 1, "Garchomp +1 Spe from DD");
        assert_eq!(b.p2.team[0].boosts[0], 1, "Mirror Herb copied +1 Atk");
        assert_eq!(b.p2.team[0].boosts[4], 1, "Mirror Herb copied +1 Spe");
        assert_eq!(b.p2.team[0].item_id, u16::MAX, "Mirror Herb consumed");
    }

