        let p1_json = r#"[
            {"species":"fluttermane","level":50,"ability":"protosynthesis","item":"boosterenergy","nature":"timid","moves":["moonblast","shadowball","dazzlinggleam","mysticalfire"],"evs":{"spa":252,"spe":252,"hp":4}}
        ]"#;
