    #[test]
    fn accuracy_drop_reduces_hit_rate() {
        // Hurricane has 70% accuracy. Drop attacker Acc by -2: PS
        // formula `acc * 3 / (3 + 2) = acc * 3/5` → 70 * 3/5 = 42%
        // effective accuracy. Across many trials the hit rate should
        // be roughly 42%, well below the unmodified 70%.
        let p1_json = r#"[
            {"species":"pelipper","level":50,"ability":"keeneye","item":"","nature":"modest","moves":["hurricane","weatherball","tailwind","airslash"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        // Trial count chosen so the 70% vs 42% gap is statistically
        // unambiguous; seed varies so rolls aren't pathologically
        // aligned across trials.
        let trials = 400u32;
        let mut hits_unboosted = 0u32;
        let mut hits_dropped = 0u32;
        for seed in 0..trials {
            // Baseline: Acc stage 0.
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: seed as u64 }, p1.clone(), p2.clone());
            let hp_before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            if b.p2.team[0].current_hp < hp_before {
                hits_unboosted += 1;
            }
            // Acc -2 stage on attacker.
            let mut b2 = Battle::new(BattleConfig { format: Format::Singles, seed: seed as u64 }, p1.clone(), p2.clone());
            b2.p1.team[0].boosts[5] = -2;
            let hp_before2 = b2.p2.team[0].current_hp;
            b2.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            if b2.p2.team[0].current_hp < hp_before2 {
                hits_dropped += 1;
            }
        }
        let rate_a = hits_unboosted * 100 / trials;
        let rate_b = hits_dropped * 100 / trials;
        // Sanity: unmodified hits near 70%, -2 Acc hits near 42%.
        // Wide windows because we only run 400 trials.
        assert!(
            rate_a >= 60 && rate_a <= 80,
            "unmodified Hurricane hit rate {rate_a}% (expected ≈70%)"
        );
        assert!(
            rate_b >= 30 && rate_b <= 55,
            "-2 Acc Hurricane hit rate {rate_b}% (expected ≈42%)"
        );
        assert!(
            rate_a > rate_b + 10,
            "Acc drop should reduce hit rate by >10pp; got {rate_a} vs {rate_b}"
        );
    }

    #[test]
    fn evasion_boost_reduces_incoming_hit_rate() {
        // Mirror of the Acc test on the defender side: +2 evasion
        // turns 70% Hurricane into ≈42% effective.
        let p1_json = r#"[
            {"species":"pelipper","level":50,"ability":"keeneye","item":"","nature":"modest","moves":["hurricane","weatherball","tailwind","airslash"]}
        ]"#;
        let p2_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"careful","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let trials = 300u32;
        let mut hits = 0u32;
        for seed in 0..trials {
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: seed as u64 }, p1.clone(), p2.clone());
            b.p2.team[0].boosts[6] = 2; // +2 evasion
            let hp_before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            if b.p2.team[0].current_hp < hp_before { hits += 1; }
        }
        let rate = hits * 100 / trials;
        assert!(
            rate >= 30 && rate <= 55,
            "+2 evasion should reduce 70%-acc hit to ≈42%; got {rate}%"
        );
    }

    #[test]
    fn cute_charm_infatuates_opposite_gender_contact_attacker_and_respects_gates() {
        // Clefable has Cute Charm. A male contact attacker should be
        // infatuated ≈30% of the time; a same-gender attacker is never
        // infatuated (gender gate). Body Slam (Snorlax, Normal) makes
        // contact and isn't blocked.
        let p1_json = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["bodyslam","rest","sleeptalk","crunch"]}
        ]"#;
        let p2_json = r#"[
            {"species":"clefable","level":50,"ability":"cutecharm","item":"","nature":"calm","moves":["moonblast","softboiled","calmmind","thunderbolt"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();

        // Opposite-gender (M attacker vs F holder): proc ≈30% over trials.
        let trials = 200u32;
        let mut infatuated = 0u32;
        for seed in 0..trials {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed: seed as u64 },
                p1.clone(),
                p2.clone(),
            );
            b.p1.team[0].gender = data::Gender::Male;
            b.p2.team[0].gender = data::Gender::Female;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            if b.p1.team[0].is_attracted() {
                // Source recorded as the Cute Charm holder (P2 side 1, idx 0).
                assert_eq!(b.p1.team[0].attract_source(), Some((1, 0)));
                infatuated += 1;
            }
        }
        let rate = infatuated * 100 / trials;
        assert!(
            rate >= 15 && rate <= 45,
            "Cute Charm infatuation rate {rate}% (expected ≈30% over 200 trials)"
        );

        // Same-gender (M attacker vs M holder): never infatuated.
        for seed in 0..trials {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed: seed as u64 },
                p1.clone(),
                p2.clone(),
            );
            b.p1.team[0].gender = data::Gender::Male;
            b.p2.team[0].gender = data::Gender::Male;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            assert!(
                !b.p1.team[0].is_attracted(),
                "same-gender attacker must never be infatuated by Cute Charm"
            );
        }
    }

    #[test]
    fn cursed_body_disables_attacker_used_move_30pct_no_contact_required() {
        // Gengar has Cursed Body. A foe that lands a damaging hit (even a
        // non-contact special move) should have that move Disabled ≈30%
        // of the time. Use Snorlax's Crunch... no — use a NON-contact
        // move to prove contact isn't required: Tauros isn't handy, so
        // pick a special attacker. Use Clefable's Thunderbolt (special,
        // non-contact) into Gengar; Gengar is hit and may Disable it.
        let p1_json = r#"[
            {"species":"gengar","level":50,"ability":"cursedbody","item":"","nature":"timid","moves":["shadowball","sludgebomb","focusblast","thunderbolt"]}
        ]"#;
        let p2_json = r#"[
            {"species":"clefable","level":50,"ability":"unaware","item":"","nature":"modest","moves":["thunderbolt","moonblast","calmmind","softboiled"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();

        let trials = 200u32;
        let mut disabled = 0u32;
        for seed in 0..trials {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed: seed as u64 },
                p1.clone(),
                p2.clone(),
            );
            // P2 (Clefable) goes first with Thunderbolt (slot 0) into the
            // faster... Gengar is faster, so have Gengar pass and Clefable
            // attack to guarantee the hit lands on Gengar.
            b.step(
                &[Choice::Pass { actor_slot: 0 }],
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
            );
            if b.p2.team[0].disabled_move_slot() != 255 {
                // The disabled slot must be Thunderbolt (slot 0, the move
                // that just hit). Cursed Body sets duration 4; the standard
                // end-of-turn tick has already counted it down once by the
                // time `step` returns, so the observable value is 3.
                assert_eq!(b.p2.team[0].disabled_move_slot(), 0, "disabled the used move slot");
                assert_eq!(b.p2.team[0].disable_turns(), 3, "4-turn Disable, one end-of-turn tick applied");
                disabled += 1;
            }
        }
        let rate = disabled * 100 / trials;
        assert!(
            rate >= 15 && rate <= 45,
            "Cursed Body disable rate {rate}% (expected ≈30% over 200 trials)"
        );

        // Gate: an attacker that is ALREADY disabled is never re-disabled
        // (PS `if (source.volatiles['disable']) return`).
        for seed in 0..trials {
            let mut b = Battle::new(
                BattleConfig { format: Format::Singles, seed: seed as u64 },
                p1.clone(),
                p2.clone(),
            );
            // Pre-disable Clefable's Moonblast (slot 1); it attacks with
            // Thunderbolt (slot 0). Cursed Body must not overwrite the
            // existing Disable.
            b.p2.team[0].set_disable(4, 1);
            b.step(
                &[Choice::Pass { actor_slot: 0 }],
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
            );
            assert_eq!(
                b.p2.team[0].disabled_move_slot(), 1,
                "already-disabled attacker keeps its existing Disable slot"
            );
        }
    }

    // ---- Aroma Veil (Spritzee / Aromatisse) -------------------------
    // PS `data/abilities.ts:234` `onAllyTryAddVolatile`: the holder AND
    // every partner on its side are immune to Attract / Disable / Encore /
    // Heal Block / Taunt / Torment. Only Attract (move + Cute Charm),
    // Disable (Cursed Body), and Encore (move) are reachable in the engine
    // today; the other three volatiles have no setter yet, so their
    // immunity is vacuous-pending.

    #[test]
    fn aroma_veil_blocks_attract_move_on_holder() {
        // An Aroma Veil holder cannot be Attracted; a foe without it can.
        let attacker = r#"[
            {"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["attract","bodyslam","rest","crunch"]}
        ]"#;
        let av_holder = r#"[
            {"species":"aromatisse","level":50,"ability":"aromaveil","item":"","nature":"careful","moves":["moonblast","calmmind","protect","wish"]}
        ]"#;
        let plain = r#"[
            {"species":"clefable","level":50,"ability":"unaware","item":"","nature":"careful","moves":["moonblast","calmmind","protect","wish"]}
        ]"#;

        // Aroma Veil holder: immune.
        let p1 = TeamBuilder::from_json(attacker).unwrap();
        let p2 = TeamBuilder::from_json(av_holder).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        b.p1.team[0].gender = data::Gender::Male;
        b.p2.team[0].gender = data::Gender::Female;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(!b.p2.team[0].is_attracted(), "Aroma Veil holder immune to Attract");

        // Plain foe (no Aroma Veil): Attracted.
        let p1 = TeamBuilder::from_json(attacker).unwrap();
        let p2 = TeamBuilder::from_json(plain).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 }, p1, p2);
        b.p1.team[0].gender = data::Gender::Male;
        b.p2.team[0].gender = data::Gender::Female;
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert!(b.p2.team[0].is_attracted(), "foe without Aroma Veil is Attracted");
    }

