        use crate::damage::{calculate_damage, DamageContext};
        let p1_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"adamant","moves":["acrobatics","dragonclaw","aerialace","ironhead"]}
        ]"#;
