    #[test]
    fn synchronize_reflects_status_but_not_sleep() {
        // PS synchronize onAfterSetStatus: an opponent-inflicted brn/par/psn/
        // tox is mirrored onto the source; slp/frz are NOT.
        let holder = r#"[{"species":"espeon","level":50,"ability":"synchronize","item":"","nature":"calm","moves":["calmmind","protect","psychic","storedpower"],"evs":{"hp":252,"spd":252}}]"#;
        let foe = r#"[{"species":"smeargle","level":50,"ability":"owntempo","item":"","nature":"jolly","moves":["spore","willowisp","protect","tackle"],"evs":{"hp":252,"spe":252}}]"#;
        let run = |foe_move: u8, seed: u64| -> (Status, Status) {
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed },
                TeamBuilder::from_json(holder).unwrap(), TeamBuilder::from_json(foe).unwrap());
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }], // Espeon Calm Mind (self)
                &[Choice::Move { actor_slot: 0, move_slot: foe_move, target: Some(t(SideRef::P1, 0)) }],
            );
            (b.p1.team[0].status, b.p2.team[0].status)
        };
        // Spore (100% acc) → Espeon sleeps, Smeargle does NOT (sleep excluded).
        let (holder_s, foe_s) = run(0, 1);
        assert_eq!(holder_s, Status::Sleep, "Espeon slept by Spore");
        assert_eq!(foe_s, Status::None, "Synchronize does NOT reflect sleep");
        // Will-O-Wisp burn → reflected (seed chosen so WoW lands).
        let (holder_b, foe_b) = run(1, 4);
        assert_eq!(holder_b, Status::Burn, "Espeon burned by Will-O-Wisp");
        assert_eq!(foe_b, Status::Burn, "Synchronize reflects burn to the inflictor");
    }

    #[test]
    fn yawn_sleeps_target_at_end_of_following_turn() {
        // PS yawn: drowsy now, asleep at the END of the next turn (duration 2).
        let p1 = r#"[{"species":"smeargle","level":50,"ability":"owntempo","item":"","nature":"jolly","moves":["yawn","spore","protect","tackle"],"evs":{"spe":252}}]"#;
        let p2 = r#"[{"species":"garchomp","level":50,"ability":"roughskin","item":"","nature":"jolly","moves":["swordsdance","dragonclaw","earthquake","protect"],"evs":{"atk":252,"spe":252}}]"#;
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 },
            TeamBuilder::from_json(p1).unwrap(), TeamBuilder::from_json(p2).unwrap());
        // Turn 1: Yawn → Garchomp; Garchomp Swords Dance (no attack, nobody dies).
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
        );
        assert_eq!(b.p2.team[0].status, Status::None, "not asleep the turn Yawn lands");
        assert!(b.p2.team[0].volatiles.has(crate::pokemon::VolatileKind::Yawn), "drowsy applied");
        // Turn 2: act again; asleep at end of turn.
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 2, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
        );
        assert_eq!(b.p2.team[0].status, Status::Sleep, "asleep at end of the following turn");
        assert!(!b.p2.team[0].volatiles.has(crate::pokemon::VolatileKind::Yawn), "drowsy cleared");
    }

    #[test]
    fn knock_off_no_boost_or_removal_vs_own_mega_stone() {
        // Knock Off neither ×1.5-boosts nor removes a holder's own Mega Stone
        // (PS canKnockOffItem false). vs a normal item it does both.
        // (Conformance out_179459f0d9: Knock Off into Banette @ Banettite.)
        let run = |item: &str| -> (u16, bool, bool) {
            let p1 = r#"[{"species":"mew","level":50,"ability":"synchronize","item":"","nature":"hardy","moves":["knockoff","psychic","protect","softboiled"],"evs":{"hp":252}}]"#;
            let p2 = format!(r#"[{{"species":"banette","level":50,"ability":"insomnia","item":"{item}","nature":"bold","moves":["shadowclaw","nightshade","destinybond","willowisp"],"evs":{{"hp":252,"def":252}}}}]"#);
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 },
                TeamBuilder::from_json(p1).unwrap(), TeamBuilder::from_json(&p2).unwrap());
            let before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P1, 0)) }], // Night Shade (fixed 50, no contact)
            );
            let dmg = before.saturating_sub(b.p2.team[0].current_hp);
            let kept = b.p2.team[0].item_id != u16::MAX;
            (dmg, kept, b.p2.team[0].is_alive())
        };
        let (mega_dmg, mega_kept, mega_alive) = run("banettite");
        let (norm_dmg, norm_kept, norm_alive) = run("lumberry");
        assert!(mega_alive && norm_alive, "Banette must survive both for a fair compare");
        assert!(mega_kept, "own Mega Stone is NOT knocked off");
        assert!(!norm_kept, "a normal item IS knocked off");
        assert!(mega_dmg < norm_dmg, "no ×1.5 vs a Mega Stone ({mega_dmg} < {norm_dmg})");
    }

    #[test]
    fn gluttony_eats_pinch_berry_at_half_hp() {
        // Salac Berry normally fires at ≤1/4 HP; Gluttony raises it to ≤1/2.
        // Snorlax @ Salac at ~45% HP takes a tiny hit (Caterpie, faster, moves
        // first) → on_after_damage checks the berry.
        let run = |ability: &str| -> (bool, i8) {
            let p1 = format!(r#"[{{"species":"snorlax","level":50,"ability":"{ability}","item":"salacberry","nature":"careful","moves":["crunch","rest","bodyslam","protect"],"evs":{{"hp":252,"spd":252}}}}]"#);
            let p2 = r#"[{"species":"caterpie","level":50,"ability":"shielddust","item":"","nature":"hardy","moves":["tackle","stringshot","bugbite","protect"]}]"#;
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 },
                TeamBuilder::from_json(&p1).unwrap(), TeamBuilder::from_json(p2).unwrap());
            b.p1.team[0].current_hp = b.p1.team[0].stats.hp * 9 / 20; // ~45%
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P1, 0)) }],
            );
            (b.p1.team[0].item_id == u16::MAX, b.p1.team[0].boosts[4])
        };
        assert_eq!(run("gluttony"), (true, 1), "Gluttony eats Salac at ~45% HP (+1 Spe)");
        assert_eq!(run("thickfat"), (false, 0), "without Gluttony, Salac waits for ≤1/4 HP");
    }

    #[test]
    fn weak_armor_drops_def_raises_spe_on_physical_hit_only() {
        // PS weakarmor: physical hit → self -1 Def / +2 Spe; special hit → none.
        let p1 = r#"[{"species":"polteageist","level":50,"ability":"weakarmor","item":"focussash","nature":"timid","moves":["shadowball","storedpower","protect","nastyplot"],"evs":{"spa":252,"spe":252}}]"#;
        let p2 = r#"[{"species":"snorlax","level":50,"ability":"thickfat","item":"","nature":"adamant","moves":["earthquake","icebeam","rest","crunch"],"evs":{"atk":252}}]"#;
        let run = |atk_move: u8| -> [i8; 7] {
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 7 },
                TeamBuilder::from_json(p1).unwrap(), TeamBuilder::from_json(p2).unwrap());
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Move { actor_slot: 0, move_slot: atk_move, target: Some(t(SideRef::P1, 0)) }],
            );
            b.p1.team[0].boosts
        };
        let phys = run(0); // Body Slam (physical)
        assert_eq!(phys[1], -1, "Weak Armor -1 Def on physical hit");
        assert_eq!(phys[4], 2, "Weak Armor +2 Spe on physical hit");
        let spec = run(1); // Ice Beam (special)
        assert_eq!((spec[1], spec[4]), (0, 0), "no Weak Armor on a special hit");
    }

    #[test]
    fn pinch_ability_boosts_matching_type_at_low_hp() {
        // Blaze ×1.5 on Fire moves when the holder is at ≤1/3 max HP. PS
        // data/abilities.ts:blaze (Overgrow/Torrent/Swarm share the shape).
        // Was unimplemented (39 of 100 teams carry a pinch ability).
        let p1 = r#"[{"species":"charizard","level":50,"ability":"blaze","item":"","nature":"modest","moves":["flamethrower","airslash","dragonpulse","protect"],"evs":{"spa":252}}]"#;
        let p2 = r#"[{"species":"blissey","level":50,"ability":"naturalcure","item":"","nature":"calm","moves":["seismictoss","softboiled","toxic","protect"],"evs":{"hp":252,"spd":252}}]"#;
        let mk = |low_hp: bool| -> u16 {
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 },
                TeamBuilder::from_json(p1).unwrap(), TeamBuilder::from_json(p2).unwrap());
            if low_hp {
                b.p1.team[0].current_hp = b.p1.team[0].stats.hp / 3; // ≤ 1/3 max
            }
            let before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            before - b.p2.team[0].current_hp
        };
        let full = mk(false);
        let low = mk(true);
        assert!(low > full, "Blaze boosts Fire damage at low HP ({low} > {full})");
        let ratio = (low as u32) * 1000 / (full.max(1) as u32);
        assert!((1400..=1600).contains(&ratio), "Blaze ≈×1.5 expected, got ×{}/1000", ratio);
        // Control: just above 1/3 HP → no boost.
        let mut c = Battle::new(BattleConfig { format: Format::Singles, seed: 1 },
            TeamBuilder::from_json(p1).unwrap(), TeamBuilder::from_json(p2).unwrap());
        c.p1.team[0].current_hp = c.p1.team[0].stats.hp / 3 + 1; // > 1/3
        let before = c.p2.team[0].current_hp;
        c.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
            &[Choice::Pass { actor_slot: 0 }],
        );
        assert_eq!(before - c.p2.team[0].current_hp, full, "no Blaze boost just above 1/3 HP");
    }

    #[test]
    fn haze_clears_all_stat_stages_both_sides() {
        // PS data/moves.ts:haze onHitField clearBoosts on every active mon,
        // both sides. Was unimplemented (conformance out_39d6c0803b: a Swords
        // Dance survived the foe's Haze). Set boosts on both sides, Haze, check
        // all reset — including the user's own.
        let p1_json = r#"[
            {"species":"weezing","level":50,"ability":"levitate","nature":"bold","moves":["haze","sludgebomb","willowisp","protect"]}
        ]"#;
        let p2_json = r#"[
            {"species":"garchomp","level":50,"ability":"roughskin","nature":"jolly","moves":["swordsdance","dragonclaw","earthquake","protect"]}
        ]"#;
        let p1 = TeamBuilder::from_json(p1_json).unwrap();
        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        b.p1.team[0].boosts = [2, 1, 0, 0, 0, 0, 0];
        b.p2.team[0].boosts = [-1, 0, 3, 2, 4, 0, 0];
        b.step(
            &[Choice::Move { actor_slot: 0, move_slot: 0, target: None }],
            &[Choice::Move { actor_slot: 0, move_slot: 3, target: None }], // Garchomp Protect
        );
        assert_eq!(b.p1.team[0].boosts, [0; 7], "Haze clears the user's own boosts");
        assert_eq!(b.p2.team[0].boosts, [0; 7], "Haze clears the foe's boosts (through Protect)");
    }

