        // heal PLUS cureStatus. Burned, pre-damaged user heals + cures.
        let p1_json = r#"[
            {"species":"zarude","level":50,"ability":"leafguard","nature":"adamant","moves":["junglehealing","powerwhip","darkestlariat","protect"],"evs":{"hp":252}}
        ]"#;
