        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 1 }, p1, p2);
        let max = b.p1.team[0].stats.hp as u32;
        b.p1.team[0].current_hp = (max / 2) as u16;
        b.p1.team[0].status = Status::Burn;
