        let p2 = TeamBuilder::from_json(p2_json).unwrap();
        let mut b = Battle::new(BattleConfig { format: Format::Singles, seed: 3 }, p1, p2);
        assert_ne!(b.weather, crate::weather::Weather::Sand,
                   "Sand Spit must NOT set Sand on switch-in");
