    #[test]
    fn spirit_break_and_struggle_bug_drop_spa() {
        // PS data/moves.ts: spiritbreak / strugglebug both
        // `secondary: { chance: 100, boosts: { spa: -1 } }` (index 2).
        // Struggle Bug is a spread move; Spirit Break is single-target.
        assert_eq!(super::stat_drop_secondary("spiritbreak"), Some((2, -1, 100)));
        assert_eq!(super::stat_drop_secondary("strugglebug"), Some((2, -1, 100)));
        // Gameplay: Spirit Break always drops the target's SpA by 1.
        let p1_json = r#"[
            {"species":"grimmsnarl","level":50,"ability":"prankster","item":"","nature":"adamant","moves":["spiritbreak","tackle","thunderwave","protect"],"evs":{"atk":252,"hp":4}}
        ]"#;
        let p2_json = r#"[
            {"species":"blissey","level":50,"ability":"naturalcure","item":"","nature":"bold","moves":["recover","tackle","calmmind","ember"],"evs":{"hp":252,"def":252}}
        ]"#;
        for seed in 0u64..16 {
            let p1 = TeamBuilder::from_json(p1_json).unwrap();
            let p2 = TeamBuilder::from_json(p2_json).unwrap();
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed }, p1, p2);
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            assert_eq!(b.p2.team[0].boosts[2], -1, "Spirit Break -1 SpA seed {seed}");
        }
    }

    #[test]
    fn lunge_and_pounce_always_drop_their_stat() {
        // Lunge = 100% Atk -1, Pounce = 100% Spe -1 (PS data/moves.ts
        // 10608 / 13633). Sweep seeds at a bulky passive target and confirm
        // the right stat drops every time and the other is untouched.
        let p1_json = r#"[
            {"species":"golisopod","level":50,"ability":"emergencyexit","item":"","nature":"adamant","moves":["lunge","pounce","liquidation","protect"],"evs":{"atk":252,"hp":4,"spe":252}}
        ]"#;
        let p2_json = r#"[
            {"species":"toxapex","level":50,"ability":"regenerator","item":"","nature":"bold","moves":["recover","scald","toxic","haze"],"evs":{"hp":252,"def":252,"spd":4}}
        ]"#;
        for seed in 0u64..48 {
            // Lunge (move slot 0) — Atk -1.
            let p1 = TeamBuilder::from_json(p1_json).unwrap();
            let p2 = TeamBuilder::from_json(p2_json).unwrap();
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed }, p1, p2);
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            assert!(b.p2.team[0].is_alive(), "Lunge target must survive seed {seed}");
            assert_eq!(b.p2.team[0].boosts[0], -1, "Lunge -1 Atk seed {seed}");
            assert_eq!(b.p2.team[0].boosts[4], 0, "Lunge leaves Spe seed {seed}");

            // Pounce (move slot 1) — Spe -1.
            let p1 = TeamBuilder::from_json(p1_json).unwrap();
            let p2 = TeamBuilder::from_json(p2_json).unwrap();
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed }, p1, p2);
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 1, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            assert!(b.p2.team[0].is_alive(), "Pounce target must survive seed {seed}");
            assert_eq!(b.p2.team[0].boosts[4], -1, "Pounce -1 Spe seed {seed}");
            assert_eq!(b.p2.team[0].boosts[0], 0, "Pounce leaves Atk seed {seed}");
        }
    }

    #[test]
    fn protean_grants_stab_on_triggering_move() {
        // Protean/Libero retype the user to the move's type BEFORE the move
        // resolves, so the very move that triggers it gains STAB. Greninja
        // (Water/Dark) Flamethrower: with Protean it becomes Fire-typed and the
        // hit gets ×1.5 STAB; with Torrent it stays Water/Dark and gets none.
        // Same seed → identical damage roll, so the only difference is STAB.
        // PS data/abilities.ts:protean onPrepareHit.
        let mk_protean = |seed: u64| {
            let p1_json = r#"[
                {"species":"greninja","level":50,"ability":"protean","item":"","nature":"timid","moves":["flamethrower","surf","darkpulse","protect"],"evs":{"spa":252,"spe":252}}
            ]"#;
            let p2_json = r#"[
                {"species":"snorlax","level":50,"ability":"gluttony","item":"","nature":"careful","moves":["bodyslam","rest","crunch","yawn"],"evs":{"hp":252,"spd":252}}
            ]"#;
            let p1 = TeamBuilder::from_json(p1_json).unwrap();
            let p2 = TeamBuilder::from_json(p2_json).unwrap();
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed }, p1, p2);
            let before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            before - b.p2.team[0].current_hp
        };
        let mk_plain = |seed: u64| {
            let p1_json = r#"[
                {"species":"greninja","level":50,"ability":"torrent","item":"","nature":"timid","moves":["flamethrower","surf","darkpulse","protect"],"evs":{"spa":252,"spe":252}}
            ]"#;
            let p2_json = r#"[
                {"species":"snorlax","level":50,"ability":"gluttony","item":"","nature":"careful","moves":["bodyslam","rest","crunch","yawn"],"evs":{"hp":252,"spd":252}}
            ]"#;
            let p1 = TeamBuilder::from_json(p1_json).unwrap();
            let p2 = TeamBuilder::from_json(p2_json).unwrap();
            let mut b = Battle::new(BattleConfig { format: Format::Singles, seed }, p1, p2);
            let before = b.p2.team[0].current_hp;
            b.step(
                &[Choice::Move { actor_slot: 0, move_slot: 0, target: Some(t(SideRef::P2, 0)) }],
                &[Choice::Pass { actor_slot: 0 }],
            );
            before - b.p2.team[0].current_hp
        };
        let protean = mk_protean(7);
        let plain = mk_plain(7);
        // ~×1.5 STAB; assert a clear boost (allow rounding slack).
        let ratio_x100 = (protean as u32) * 100 / (plain.max(1) as u32);
        assert!((140..=160).contains(&ratio_x100),
            "Protean grants ~×1.5 STAB on the triggering move: protean={protean} plain={plain} (×{ratio_x100}/100)");
    }

